+        private final InternalValue value;
+
+        private BytesRef current;
+        private int count;
+
+        CountedKeywordSortedBinaryDocValues(BinaryDocValues values) {
+            this.values = values;
+            this.value = new InternalValue();
+            try {
+                this.value.reset(values.binaryValue());
