+        @Override
+        public BytesRef nextValue() throws IOException {
+            if (count == 0) {
+                if (value.next() == false) {
+                    throw new NoSuchElementException();
+                }
+                count = value.count;
+                current = BytesRefs.toBytesRef(value.value);
+            }
+            count--;
+            return current;
+        }
+    }
