+
+    @Override
+    protected ValuesSourceRegistry.RegistryKey<?> getRegistryKey() {
+        // method is unused - no need to implement it
+        return null;
+    }
+
+    @Override
+    protected ValuesSourceType defaultValueSourceType() {
