+        abstract R buildResult(long owningBucketOrd, long otherDocCount, B[] topBuckets);
+
+        /**
+         * Build an "empty" result. Only called if there isn't any data on this
+         * shard.
+         */
+        abstract R buildEmptyResult();
+
