+        abstract R buildEmptyResult();
+
+        /**
+         * Build an "empty" result for a particular bucket ordinal. Called when
+         * there aren't any values for the field on this shard.
+         */
+        abstract R buildNoValuesResult(long owningBucketOrdinal);
